import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { renderBrandMarkSvg } from "../packages/ui/src/brand/brand.js";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const targets = [
  path.join(root, "altftoolweb", "public", "brand", "altftool-mark.svg"),
  path.join(root, "altftoolwebadmin", "public", "brand", "altftool-mark.svg"),
];
const sourceBanner =
  "<!-- Generated by npm run brand:sync from packages/ui/src/brand/brand.js. -->\n";
const svg = `${sourceBanner}${renderBrandMarkSvg()}\n`;

await Promise.all(
  targets.map(async (target) => {
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, svg, "utf8");
  }),
);

console.log(`Synced ${targets.length} canonical AltFTool brand assets.`);
